/**
 * Admin Dashboard Page
 * Premium admin dashboard with analytics and management
 */

import React, { useState, useEffect } from 'react';
import LoadingSpinner from '../components/LoadingSpinner';
import api from '../services/api';
import './AdminDashboard.css';

const AdminDashboard = () => {
  const [dashboard, setDashboard] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    fetchDashboard();
  }, []);

  const fetchDashboard = async () => {
    try {
      const response = await api.get('/dashboard/admin');
      setDashboard(response.data.dashboard);
      setError('');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to fetch dashboard');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await fetchDashboard();
  };

  if (loading) {
    return <LoadingSpinner message="Loading admin dashboard..." />;
  }

  if (error && !dashboard) {
    return (
      <div className="admin-dashboard-page">
        <div className="admin-container">
          <div className="error-container">
            <h2>⚠️ Error Loading Dashboard</h2>
            <p>{error}</p>
            <button className="refresh-btn" onClick={handleRefresh}>
              🔄 Retry
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="admin-dashboard-page">
      <div className="admin-container">
        <div className="dashboard-header">
          <h1>📊 Admin Dashboard</h1>
          <button 
            className="refresh-btn" 
            onClick={handleRefresh}
            disabled={refreshing}
          >
            🔄 {refreshing ? 'Refreshing...' : 'Refresh'}
          </button>
        </div>

        {/* Stats Grid */}
        <div className="stats-grid">
          <div className="stat-card">
            <span className="stat-icon">👥</span>
            <div className="stat-content">
              <h3>Total Users</h3>
              <p className="stat-value">{dashboard?.totalUsers || 0}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">📅</span>
            <div className="stat-content">
              <h3>Total Events</h3>
              <p className="stat-value">{dashboard?.totalEvents || 0}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">🎫</span>
            <div className="stat-content">
              <h3>Total Bookings</h3>
              <p className="stat-value">{dashboard?.totalBookings || 0}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">💰</span>
            <div className="stat-content">
              <h3>Total Revenue</h3>
              <p className="stat-value">₹{dashboard?.totalRevenue || 0}</p>
            </div>
          </div>
        </div>

        {/* Bookings by Status */}
        <div className="chart-section">
          <h2>📈 Bookings by Status</h2>
          <div className="status-overview">
            {Object.entries(dashboard?.bookingsByStatus || {}).map(([status, count]) => (
              <div key={status} className="status-item">
                <span className="status-name">{status}</span>
                <span className="status-count">{count}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Bookings */}
        <div className="table-section">
          <h2>📋 Recent Bookings</h2>
          <div className="table-wrapper">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>User</th>
                  <th>Event</th>
                  <th>Tickets</th>
                  <th>Amount</th>
                  <th>Date</th>
                </tr>
              </thead>
              <tbody>
                {dashboard?.recentBookings && dashboard.recentBookings.length > 0 ? (
                  dashboard.recentBookings.map((booking, idx) => (
                    <tr key={idx}>
                      <td>
                        <span style={{ fontWeight: '600', color: '#1e293b' }}>
                          {booking.userName}
                        </span>
                      </td>
                      <td>{booking.eventName}</td>
                      <td>
                        <span style={{ 
                          background: 'rgba(59, 130, 246, 0.1)',
                          color: '#3b82f6',
                          padding: '0.35rem 0.75rem',
                          borderRadius: '6px',
                          fontWeight: '600',
                          display: 'inline-block'
                        }}>
                          {booking.tickets}
                        </span>
                      </td>
                      <td style={{ fontWeight: '700', color: '#1e40af' }}>
                        ₹{booking.amount}
                      </td>
                      <td style={{ color: '#94a3b8', fontSize: '0.9rem' }}>
                        {new Date(booking.date).toLocaleDateString('en-IN')}
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" className="admin-table-empty">
                      📭 No recent bookings yet
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Top Events */}
        <div className="table-section">
          <h2>⭐ Top Events</h2>
          <div className="table-wrapper">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Event Name</th>
                  <th>Bookings</th>
                  <th>Revenue</th>
                </tr>
              </thead>
              <tbody>
                {dashboard?.topEvents && dashboard.topEvents.length > 0 ? (
                  dashboard.topEvents.map((event, idx) => (
                    <tr key={idx}>
                      <td>
                        <span style={{ fontWeight: '600', color: '#1e293b' }}>
                          {event.eventName}
                        </span>
                      </td>
                      <td>
                        <span style={{ 
                          background: 'rgba(16, 185, 129, 0.1)',
                          color: '#059669',
                          padding: '0.35rem 0.75rem',
                          borderRadius: '6px',
                          fontWeight: '600',
                          display: 'inline-block'
                        }}>
                          {event.bookings}
                        </span>
                      </td>
                      <td style={{ fontWeight: '700', color: '#1e40af' }}>
                        ₹{event.revenue}
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="3" className="admin-table-empty">
                      📭 No events data available
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
